// secret-guard: hide secrets from Claude.
//
// tool.call: let the tool run, then scan everything it returned and replace API keys,
// tokens and passwords with a placeholder before Claude reads the result.
// ui.render (AbovePrompt): one line with how many secrets were hidden this session.
// /secrets: print what was hidden (kinds only, never the values).
//
// The host reads on(...) and $.noun.method(...) from source, so they are spelled
// literally, and helpers that take $ are top-level functions.

const RULES = [
  { kind: "Anthropic key", re: /sk-ant-[A-Za-z0-9_-]{20,}/g },
  { kind: "OpenAI key", re: /sk-(?:proj-)?[A-Za-z0-9_-]{20,}/g },
  { kind: "GitHub token", re: /gh[pousr]_[A-Za-z0-9]{30,}/g },
  { kind: "AWS key", re: /AKIA[0-9A-Z]{16}/g },
  { kind: "Google key", re: /AIza[0-9A-Za-z_-]{35}/g },
  { kind: "Slack token", re: /xox[baprs]-[A-Za-z0-9-]{10,}/g },
  { kind: "Stripe key", re: /(?:sk|rk)_live_[A-Za-z0-9]{20,}/g },
  { kind: "private key", re: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g },
  // NAME_KEY=value / NAME_TOKEN: value lines, e.g. in .env files and configs
  { kind: "env secret", re: /\b([A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD|PASSWD)[A-Z0-9_]*)(\s*[=:]\s*)("?)(?!\[hidden)([^\s"'#]{6,})\3/g, keepName: true },
];
const MASK = "[hidden by secret-guard]";

let hidden = 0;
const seen = new Set(); // each secret counts once, however often it shows up
let last = "";
const kinds = {};

export function register(on) {
  on("session.start", async ($, e, next) => {
    const result = await next(e);
    await $.command.register({ name: "secrets", description: "secret-guard: what was hidden from Claude this session" });
    return result;
  });

  on("tool.call", async ($, e, next) => {
    const result = await next(e);
    const before = hidden;
    const clean = scrub(result, e.tool);
    if (hidden > before) {
      $.ui.log(`hid ${hidden - before} secret${hidden - before > 1 ? "s" : ""} from Claude (${e.tool})`);
      $.ui.invalidate("ui.render");
    }
    return clean;
  }).catch(async ($, e, next) => {
    // fail closed: if scanning broke, Claude gets nothing rather than a possible secret
    if (next.called) return { deny: "secret-guard could not scan this result, so it was withheld." };
    return next(e);
  });

  on("command.run", { command: "secrets" }, async () => {
    if (!hidden) return { text: "no secrets seen yet" };
    const list = Object.entries(kinds).map(([k, n]) => `${n} × ${k}`).join(", ");
    return { text: `hid ${hidden} secret${hidden > 1 ? "s" : ""} from Claude this session: ${list}` };
  });

  on("ui.render", { component: "AbovePrompt" }, ($, e, next) => {
    if (e.hasSurvey) return next(e);
    const { Box, Text } = $.ui.resolve(e);
    const parts = [
      Text({ color: hidden ? "green" : "gray", bold: true, children: "■ secret-guard" }),
      Text({ children: hidden ? `  ${hidden} secret${hidden > 1 ? "s" : ""} hidden from Claude` : "  watching tool output" }),
    ];
    if (last && (e.bodyColumns ?? 80) >= 70) parts.push(Text({ dimColor: true, children: `   last: ${last}` }));
    return Box({ flexDirection: "row", paddingX: 1, children: parts });
  });
}

// Walk any result shape and redact every string in it.
function scrub(value, tool) {
  if (typeof value === "string") return redact(value, tool);
  if (Array.isArray(value)) return value.map((v) => scrub(v, tool));
  if (value && typeof value === "object") {
    const out = {};
    for (const [k, v] of Object.entries(value)) out[k] = scrub(v, tool);
    return out;
  }
  return value;
}

function redact(text, tool) {
  let out = text;
  for (const rule of RULES) {
    out = out.replace(rule.re, (...m) => {
      if (m[0].includes(MASK)) return m[0];
      const value = rule.keepName ? m[4] : m[0];
      if (!seen.has(value)) {
        seen.add(value);
        hidden += 1;
        kinds[rule.kind] = (kinds[rule.kind] ?? 0) + 1;
        last = `${rule.kind} in ${tool} output`;
      }
      return rule.keepName ? `${m[1]}${m[2]}${MASK}` : MASK;
    });
  }
  return out;
}

